const actividad = $('IA2 - Generación').first().json.output;
const evaluacionIA = $('IA3 - Evaluación').first().json.output;

const rag =
  $('Unificar contexto RAG').first().json.contexto_rag ?? '';

// Texto completo de la actividad
const texto = [
  actividad.titulo ?? '',
  actividad.enunciado ?? '',
  actividad.objetivo ?? '',
  ...(actividad.conceptos_utilizados ?? [])
]
  .join(' ')
  .toLowerCase();

const textoRag = String(rag).toLowerCase();

const violaciones = [];

// ---------------------------------------------------------
// 1. Explicaciones causales no respaldadas
// ---------------------------------------------------------

if (
  texto.includes('por qué range') ||
  texto.includes('por qué la función range')
) {
  violaciones.push(
    'Se solicita una explicación causal sobre range() que puede no estar respaldada explícitamente por el RAG.'
  );
}

// ---------------------------------------------------------
// 2. Conceptos no presentes en el material
// ---------------------------------------------------------

const expresionesControladas = [
  'límite de range',
  'límite superior',
  'valor superior',
  'off-by-one',
  'errores comunes'
];

for (const expresion of expresionesControladas) {
  if (
    texto.includes(expresion) &&
    !textoRag.includes(expresion)
  ) {
    violaciones.push(
      `Se introduce "${expresion}", que no aparece explícitamente en el RAG.`
    );
  }
}

// ---------------------------------------------------------
// 3. Detectar ejemplos numéricos de range()
// ---------------------------------------------------------

function extraerRangeNumericos(contenido) {
  return [
    ...String(contenido).matchAll(/range\s*\(\s*(\d+)\s*\)/gi)
  ].map(match => Number(match[1]));
}

const ejemplosPermitidos = new Set(
  extraerRangeNumericos(textoRag)
);

const ejemplosActividad = [
  ...new Set(extraerRangeNumericos(texto))
];

const ejemplosNoPermitidos = ejemplosActividad.filter(
  numero => !ejemplosPermitidos.has(numero)
);

if (ejemplosNoPermitidos.length > 0) {
  violaciones.push(
    `La actividad introduce ejemplos de range() no presentes explícitamente en el RAG: ${ejemplosNoPermitidos
      .map(numero => `range(${numero})`)
      .join(', ')}.`
  );
}

// ---------------------------------------------------------
// 4. Generalización range(n)
// ---------------------------------------------------------

if (
  texto.includes('range(n)') &&
  !textoRag.includes('range(n)')
) {
  violaciones.push(
    'Se generaliza el ejemplo disponible a range(n), aunque esa regla no aparece explícitamente en el RAG.'
  );
}

// ---------------------------------------------------------
// 5. Casos inversos o inferencias no respaldadas
// ---------------------------------------------------------

if (
  texto.includes('cuando no se conoce') ||
  texto.includes('si no se conoce')
) {
  if (
    !textoRag.includes('cuando no se conoce') &&
    !textoRag.includes('si no se conoce')
  ) {
    violaciones.push(
      'Se plantea un caso contrario que requiere una inferencia no explícita en el RAG.'
    );
  }
}

// ---------------------------------------------------------
// Resultado determinista
// ---------------------------------------------------------

const guardrailValido = violaciones.length === 0;

return {
  json: {
    evaluacion_ia: evaluacionIA,

    guardrail_determinista: {
      valido: guardrailValido,
      violaciones
    },

    valida_final:
      evaluacionIA.valida === true &&
      guardrailValido === true
  }
};

